INSERT INTO exercises (id, name, category, equipment, target, muscle_group, secondary_muscles, instructions_es, image_url, gif_url) VALUES
('0173', 'cable incline triceps extension', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Ajusta la máquina de cable a una posición de polea baja. Sujeta una barra recta al cable. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono y extiende los brazos rectos por encima de la cabeza. Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado. Flexiona los codos y baja la barra detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0173-Hx1WC8I.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0173-Hx1WC8I.gif'),
('0174', 'cable judo flip', 'waist', 'cable', 'abs', 'obliques', '{"obliques","shoulders"}', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con ambas manos a la altura del pecho, con las palmas hacia abajo. Activa el core y rota el torso hacia la derecha, jalando el cable a través del cuerpo. Mientras rotas, gira el pie de atrás y permite que las caderas roten de forma natural. Extiende los brazos completamente y termina el movimiento llevando la agarradera del cable por encima del hombro. Vuelve a la posición inicial revirtiendo el movimiento, rotando el torso de regreso al centro. Repite el movimiento en el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0174-MvQPqVW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0174-MvQPqVW.gif'),
('0860', 'cable kickback', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Mantén la parte superior del brazo cerca del cuerpo y el codo flexionado en un ángulo de 90 grados. Extiende el antebrazo hacia atrás, enderezando el brazo por completo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0860-HEJ6DIX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0860-HEJ6DIX.gif'),
('0175', 'cable kneeling crunch', 'waist', 'cable', 'abs', 'obliques', '{"obliques"}', 'Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas de espaldas a la máquina. Sujeta la agarradera de cuerda con ambas manos y colócala detrás de la cabeza, manteniendo los codos hacia afuera a los lados. Manteniendo las caderas inmóviles, flexiona la cintura y encoge el torso hacia los muslos. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0175-WW95auq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0175-WW95auq.gif'),
('3697', 'cable kneeling rear delt row (with rope) (male)', 'shoulders', 'cable', 'delts', 'trapezius', '{"trapezius","rhomboids","biceps"}', 'Sujeta una agarradera de cuerda a una polea baja y ponte de rodillas frente a la máquina. Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y extiende los brazos completamente frente a ti. Manteniendo la espalda recta y el core activado, jala la cuerda hacia el cuerpo retrayendo los omóplatos. Aprieta los omóplatos al final del movimiento y mantén la posición por una breve pausa. Libera lentamente la tensión y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3697-G61cXLk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3697-G61cXLk.gif'),
('0176', 'cable kneeling triceps extension', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas frente a la máquina de cable. Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y lleva las manos a los lados de la cabeza. Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio. Extiende los antebrazos contrayendo los tríceps hasta que los brazos queden completamente extendidos. Haz una pausa por un momento y luego vuelve lentamente a la posición inicial flexionando los codos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0176-KWdF2JI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0176-KWdF2JI.gif'),
('2330', 'cable lat pulldown full range of motion', 'back', 'cable', 'lats', 'biceps', '{"biceps","rhomboids","rear deltoids"}', 'Siéntate en la máquina de jalón al pecho con las rodillas colocadas debajo de las almohadillas. Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros. Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar. Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2330-LEprlgG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2330-LEprlgG.gif'),
('0177', 'cable lateral pulldown (with rope attachment)', 'back', 'cable', 'lats', 'biceps', '{"biceps","forearms"}', 'Sujeta un accesorio de cuerda a la máquina de cable en una posición alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia atrás. Jala la cuerda hacia los costados, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento. Libera lentamente la tensión y permite que la cuerda vuelva a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0177-CuaWCmC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0177-CuaWCmC.gif'),
('2616', 'cable lateral pulldown with v-bar', 'back', 'cable', 'lats', 'biceps', '{"biceps","forearms"}', 'Siéntate en la máquina de jalón de cable y agarra el accesorio en V con un agarre prono. Ajusta la almohadilla de rodillas para que tus muslos queden asegurados debajo de ella. Mantén la espalda recta e inclínate ligeramente hacia atrás. Jala el accesorio en V hacia la parte superior del pecho manteniendo los codos cerca del cuerpo. Aprieta los músculos de la espalda en la parte baja del movimiento. Regresa lentamente el accesorio en V a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2616-4c9BhzB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2616-4c9BhzB.gif'),
('0178', 'cable lateral raise', 'shoulders', 'cable', 'delts', 'traps', '{"traps","triceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas del cable con un agarre prono. Mantén los brazos rectos y el core activado. Levanta los brazos hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0178-goJ6ezq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0178-goJ6ezq.gif'),
('0179', 'cable low fly', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Sujeta las agarraderas a las poleas bajas de una máquina de cable y selecciona un peso adecuado. Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados, manteniendo una ligera flexión en los codos. Manteniendo el control, lleva lentamente los brazos hacia adelante con un movimiento amplio, cruzándolos frente al cuerpo. Haz una pausa por un momento en el punto más alto del movimiento, sintiendo el estiramiento en los músculos del pecho. Invierte el movimiento y regresa lentamente los brazos a la posición inicial, manteniendo la tensión en los músculos del pecho durante todo el recorrido. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0179-FVmZVhk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0179-FVmZVhk.gif'),
('0180', 'cable low seated row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Siéntate en la máquina con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0180-hvV79Si.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0180-hvV79Si.gif'),
('1634', 'cable lying bicep curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Coloca una barra recta en una máquina de cable con polea baja. Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Extiende los brazos por completo, manteniendo los codos cerca de los costados. Manteniendo la parte superior de los brazos inmóvil, exhala y curva la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1634-otqIxU4.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1634-otqIxU4.gif'),
('0182', 'cable lying close-grip curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Coloca una barra recta en una máquina de cable con polea baja. Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Extiende los brazos por completo, manteniendo los codos cerca de los costados. Manteniendo la parte superior de los brazos inmóvil, curva la barra hacia el pecho contrayendo los bíceps. Haz una pausa breve en la parte alta, apretando los bíceps. Baja lentamente la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0182-61GrD55.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0182-61GrD55.gif'),
('0184', 'cable lying extension pullover (with rope attachment)', 'back', 'cable', 'lats', 'triceps', '{"triceps","shoulders"}', 'Sujeta una cuerda a una máquina de cable y coloca la polea en la posición más alta. Túmbate en un banco con la cabeza orientada hacia la máquina de cable. Sujeta la cuerda con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja lentamente la cuerda detrás de la cabeza manteniendo el control. Haz una pausa por un momento en la parte baja y luego sube lentamente la cuerda de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0184-Q2Eu1Ax.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0184-Q2Eu1Ax.gif'),
('0185', 'cable lying fly', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Sujeta las agarraderas a los cables y túmbate boca arriba en un banco con los pies apoyados planos en el suelo. Sujeta las agarraderas con las palmas una frente a la otra y los brazos extendidos rectos por encima del pecho. Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar los brazos a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0185-lJJ7Yq8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0185-lJJ7Yq8.gif'),
('0186', 'cable lying triceps extension v. 2', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Sujeta una agarradera de cuerda a una máquina de cable con polea baja. Túmbate boca arriba en un banco plano con la cabeza orientada hacia la máquina de cable. Sujeta la agarradera de cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos por encima del pecho. Manteniendo la parte superior de los brazos inmóvil, baja lentamente la agarradera de cuerda hacia la frente flexionando los codos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0186-uxJcFUU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0186-uxJcFUU.gif'),
('0188', 'cable middle fly', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Sujeta los cables a ambos lados de una máquina de cable a la altura del pecho. Ponte de pie en el centro de la máquina con un pie ligeramente delante del otro. Sujeta las agarraderas con un agarre prono y extiende los brazos hacia los lados. Mantén una ligera flexión en los codos y conserva una leve inclinación hacia adelante. Activa los músculos del pecho y lleva los brazos hacia adelante con un movimiento amplio. Haz una pausa por un momento en el centro y luego regresa lentamente los brazos a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0188-xLYSdtg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0188-xLYSdtg.gif'),
('0189', 'cable one arm bent over row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la agarradera del cable con una mano, con la palma hacia adentro, y extiende el brazo por completo. Jala la agarradera del cable hacia el cuerpo, manteniendo el codo cerca del costado, hasta que la mano llegue a la parte baja del pecho. Haz una pausa por un momento y luego extiende lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0189-EIsE3u8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0189-EIsE3u8.gif'),
('0190', 'cable one arm curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino, con la palma hacia arriba. Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0190-YTur5nR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0190-YTur5nR.gif'),
('1262', 'cable one arm decline chest fly', 'chest', 'cable', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Sujeta una agarradera en D a una máquina de cable con polea baja y coloca el banco en un ángulo declinado. Túmbate en el banco con la cabeza orientada hacia la máquina y agarra la agarradera con la mano derecha. Extiende el brazo recto por encima del pecho, manteniendo una ligera flexión en el codo. Con un movimiento controlado, baja el brazo hacia el lado hasta que la mano quede alineada con el hombro. Haz una pausa por un momento y luego invierte el movimiento para regresar el brazo a la posición inicial. Repite el número de repeticiones deseado y luego cambia al brazo izquierdo y repite el ejercicio.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1262-w4dLzSx.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1262-w4dLzSx.gif'),
('1263', 'cable one arm fly on exercise ball', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una agarradera del cable con una mano y extiende el brazo hacia el lado, paralelo al suelo. Mantén el codo ligeramente flexionado y la palma hacia adelante. Lleva lentamente el brazo a través del cuerpo, apretando los músculos del pecho. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1263-hHy8tQG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1263-hHy8tQG.gif'),
('1264', 'cable one arm incline fly on exercise ball', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado. Sujeta una agarradera del cable con una mano, con el brazo extendido y la palma hacia adentro. Manteniendo una ligera flexión en el codo, baja lentamente el brazo hacia el lado hasta que la mano quede alineada con el hombro. Haz una pausa por un momento y luego aprieta los músculos del pecho para regresar el brazo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1264-P14Dz9D.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1264-P14Dz9D.gif'),
('1265', 'cable one arm incline press', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Ajusta la máquina de cable a una posición de polea baja. Siéntate en un banco inclinado de espaldas a la máquina de cable. Sujeta la agarradera con una mano y llévala hasta la altura del hombro. Coloca los pies firmemente en el suelo y mantén una posición estable. Empuja la agarradera hacia adelante y hacia arriba, extendiendo el brazo por completo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1265-GKEH6jj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1265-GKEH6jj.gif'),
('1266', 'cable one arm incline press on exercise ball', 'chest', 'cable', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado. Sujeta una agarradera del cable con una mano y coloca el brazo en un ángulo de 90 grados con el codo flexionado. Empuja la agarradera del cable hacia adelante y hacia arriba, extendiendo el brazo por completo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1266-6t00BsF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1266-6t00BsF.gif'),
('0191', 'cable one arm lateral bent-over', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","trapezius"}', 'Ponte de pie con los pies separados a la altura de los hombros, frente a una máquina de cable. Sujeta la agarradera con una mano y retrocede un paso para crear tensión en el cable. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende el brazo hacia el lado, paralelo al suelo, con una ligera flexión en el codo. Regresa lentamente el brazo a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0191-dB07vDu.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0191-dB07vDu.gif'),
('0192', 'cable one arm lateral raise', 'shoulders', 'cable', 'delts', 'traps', '{"traps","triceps"}', 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta la agarradera del cable con una mano, con la palma hacia abajo, y colócate lo suficientemente alejado de la máquina para que haya tensión en el cable. Mantén el brazo recto y levántalo lentamente hacia el lado hasta que quede paralelo al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0192-wEulIzp.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0192-wEulIzp.gif'),
('1633', 'cable one arm preacher curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott. Mantén la espalda recta y el core activado. Curva lentamente la agarradera del cable hacia el hombro, manteniendo la parte superior del brazo contra la almohadilla. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de brazo y repite el ejercicio.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1633-eHBlPsa.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1633-eHBlPsa.gif'),
('1267', 'cable one arm press on exercise ball', 'chest', 'cable', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta. Sujeta una agarradera del cable con una mano y coloca el brazo a la altura del pecho, con el codo flexionado. Coloca la otra mano en la cadera para mantener el equilibrio. Empuja la agarradera del cable hacia adelante, extendiendo el brazo por completo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1267-MKIelrR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1267-MKIelrR.gif'),
('3563', 'cable one arm pulldown', 'back', 'cable', 'lats', 'biceps', '{"biceps","forearms"}', 'Sujeta una agarradera individual a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera con un agarre prono y extiende el brazo por completo. Mantén la espalda recta y el core activado. Jala la agarradera hacia abajo en dirección al costado, manteniendo el codo cerca del cuerpo. Haz una pausa por un momento en la parte baja del movimiento, apretando el dorsal. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3563-U5INZY6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3563-U5INZY6.gif'),
('1635', 'cable one arm reverse preacher curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Ajusta la máquina de cable de modo que la polea quede en la posición más baja. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott. Mantén la espalda recta y el core activado durante todo el ejercicio. Curva lentamente el antebrazo hacia el bíceps, manteniendo la parte superior del brazo inmóvil contra la almohadilla. Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps. Baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de brazo y repite el ejercicio.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1635-ZXnjcOQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1635-ZXnjcOQ.gif'),
('0193', 'cable one arm straight back high row (kneeling)', 'back', 'cable', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Sujeta una agarradera a una máquina de cable a la altura de la cintura. Ponte de rodillas frente a la máquina de cable y agarra la agarradera con una mano. Mantén la espalda recta y el core activado. Jala la agarradera hacia el pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0193-WrYPP2g.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0193-WrYPP2g.gif'),
('1723', 'cable one arm tricep pushdown', 'upper arms', 'cable', 'triceps', 'forearms', '{"forearms"}', 'Ponte de pie frente a una máquina de cable con un accesorio de barra recta a la altura del pecho. Sujeta la barra con un agarre prono y retrocede un paso para crear tensión en el cable. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Mantén la espalda recta y el core activado durante todo el ejercicio. Comienza con el brazo completamente extendido y perpendicular al suelo. Manteniendo la parte superior del brazo inmóvil, exhala y empuja la barra hacia abajo hasta que el brazo quede completamente extendido. Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1723-qRZ5S1N.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1723-qRZ5S1N.gif'),
('1636', 'cable overhead curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y curva la barra hacia la frente, manteniendo la parte superior de los brazos inmóvil. Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps. Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1636-wDUqY2u.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1636-wDUqY2u.gif'),
('1637', 'cable overhead curl on exercise ball', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Siéntate sobre un balón de ejercicio y sujeta la agarradera del cable con un agarre supino. Extiende los brazos completamente por encima de la cabeza, manteniendo los codos cerca de las orejas. Curva lentamente el cable hacia la frente, manteniendo la parte superior de los brazos inmóvil. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1637-ioTf098.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1637-ioTf098.gif'),
('0194', 'cable overhead triceps extension (rope attachment)', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Sujeta una cuerda a una máquina de cable en una posición alta. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y lleva las manos por encima de la cabeza. Mantén la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante. Baja lentamente la cuerda detrás de la cabeza flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0194-2IxROQ1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0194-2IxROQ1.gif'),
('1319', 'cable palm rotational row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Sujeta una agarradera a una máquina de cable a la altura de la cintura. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera con un agarre prono, con las palmas hacia abajo. Retrocede un paso para crear tensión en el cable, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Jala la agarradera hacia el cuerpo, rotando las palmas hacia arriba mientras lo haces. Aprieta los omóplatos al final del movimiento. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1319-OmQ8w0p.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1319-OmQ8w0p.gif'),
('0195', 'cable preacher curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho. Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, agarrando el accesorio del cable con un agarre supino. Mantén la espalda recta y los codos pegados a los costados. Curva lentamente el accesorio del cable hacia los hombros, apretando los bíceps en la parte más alta del movimiento. Haz una pausa por un momento y luego baja lentamente el accesorio del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0195-P2lNrGL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0195-P2lNrGL.gif'),
('1268', 'cable press on exercise ball', 'chest', 'cable', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y las rodillas en un ángulo de 90 grados. Sujeta las agarraderas del cable a la altura del pecho con las palmas hacia abajo y los codos flexionados. Activa el core y empuja las agarraderas del cable hacia adelante hasta que los brazos queden completamente extendidos. Haz una pausa por un momento y luego libera lentamente la tensión, regresando las agarraderas del cable a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1268-vAwm6rK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1268-vAwm6rK.gif'),
('0196', 'cable pull through (with rope)', 'upper legs', 'cable', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio de cuerda con ambas manos y da un paso hacia adelante, creando tensión en el cable. Flexiona las caderas y baja la parte superior del cuerpo hasta que quede paralela al suelo, manteniendo la espalda recta. Activa los glúteos y los isquiotibiales para llevar el cuerpo de vuelta hacia arriba, a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0196-OM46QHm.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0196-OM46QHm.gif'),
('0198', 'cable pulldown', 'back', 'cable', 'lats', 'biceps', '{"biceps","forearms"}', 'Ajusta la máquina de jalón de cable de modo que el asiento quede a una altura cómoda y la almohadilla de rodillas esté asegurada. Siéntate con la espalda recta y los pies apoyados planos en el suelo. Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros. Inclínate ligeramente hacia atrás y activa el core. Jala la barra del cable hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0198-RVwzP10.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0198-RVwzP10.gif'),
('0197', 'cable pulldown (pro lat bar)', 'back', 'cable', 'lats', 'biceps', '{"biceps","forearms"}', 'Ajusta la altura del asiento para que tus muslos queden paralelos al suelo y tus pies queden apoyados planos en el suelo. Sujeta la barra de jalón con un agarre prono, un poco más separado que el ancho de los hombros. Siéntate e inclínate ligeramente hacia atrás, manteniendo el pecho elevado y la espalda recta. Jala la barra hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0197-qdRxqCj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0197-qdRxqCj.gif'),
('1638', 'cable pulldown bicep curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Sujeta una barra recta a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y curva lentamente la barra hacia los muslos, manteniendo las muñecas rectas. Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps. Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1638-QTXKWPh.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1638-QTXKWPh.gif'),
('0201', 'cable pushdown', 'upper arms', 'cable', 'triceps', 'forearms', '{"forearms"}', 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y empuja la barra hacia abajo hasta que los codos queden completamente extendidos. Haz una pausa por un momento, luego inhala y regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0201-3ZflifB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0201-3ZflifB.gif'),
('0199', 'cable pushdown (straight arm) v. 2', 'back', 'cable', 'lats', 'triceps', '{"triceps","shoulders"}', 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo. Activa el core y mantén la espalda recta mientras exhalas y empujas la barra hacia abajo en dirección a los muslos. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial mientras inhalas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0199-PskORrA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0199-PskORrA.gif'),
('0200', 'cable pushdown (with rope attachment)', 'upper arms', 'cable', 'triceps', 'forearms', '{"forearms"}', 'Sujeta un accesorio de cuerda a una polea alta en una máquina de cable. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta la cuerda con un agarre prono, con las palmas una frente a la otra. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Exhala y empuja la cuerda hacia abajo extendiendo los codos hasta que los brazos queden completamente extendidos. Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial permitiendo que los codos se flexionen. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0200-dU605di.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0200-dU605di.gif'),
('0202', 'cable rear delt row (stirrups)', 'shoulders', 'cable', 'delts', 'trapezius', '{"trapezius","rhomboids","biceps"}', 'Sujeta un asa de estribo a una polea de cable baja y ponte de pie frente a la máquina. Sujeta el asa con la mano izquierda y retrocede un paso con el pie derecho, colocando el cuerpo en un ligero ángulo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Con el brazo izquierdo extendido y la palma hacia abajo, jala el asa hacia el pecho retrayendo el omóplato. Haz una pausa por un momento en la parte más alta del movimiento, apretando el omóplato. Suelta lentamente el asa de vuelta a la posición inicial y repite el número de repeticiones deseado. Cambia de lado y repite el ejercicio con el brazo derecho.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0202-yUdIGNs.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0202-yUdIGNs.gif'),
('0203', 'cable rear delt row (with rope)', 'shoulders', 'cable', 'delts', 'trapezius', '{"trapezius","rhomboids","biceps"}', 'Sujeta una agarradera de cuerda a una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera de cuerda con un agarre prono, con las palmas una frente a la otra. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Mantén los codos ligeramente flexionados y jala la cuerda hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte más alta del movimiento y luego libera lentamente la tensión, regresando a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0203-wqNPGCg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0203-wqNPGCg.gif'),
('0204', 'cable rear drive', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders","back"}', 'Sujeta una agarradera a una máquina de cable con polea baja y ponte de pie de espaldas a la máquina. Sujeta la agarradera con un agarre prono y extiende los brazos rectos frente a ti. Manteniendo los codos inmóviles, jala la agarradera de vuelta hacia el cuerpo, apretando los tríceps al final del movimiento. Regresa lentamente la agarradera a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0204-c3QQLPi.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0204-c3QQLPi.gif'),
('0205', 'cable rear pulldown', 'back', 'cable', 'lats', 'biceps', '{"biceps","rhomboids","rear deltoids"}', 'Ajusta la máquina de cable de modo que la polea quede en la posición más alta. Siéntate frente a la máquina con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta el accesorio del cable con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado. Jala el accesorio del cable hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0205-SpsOSXk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0205-SpsOSXk.gif'),
('0873', 'cable reverse crunch', 'waist', 'cable', 'abs', 'hip flexors', '{"hip flexors"}', 'Sujeta un cable a una polea baja y túmbate boca arriba sobre un tapete. Sujeta el cable con ambas manos y extiende los brazos rectos hacia el techo. Flexiona las rodillas y levanta las piernas, llevando los muslos hacia el pecho. Mientras mantienes la parte superior del cuerpo estable, curva la pelvis hacia el pecho, levantando las caderas del tapete. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0873-RqOtqD7.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0873-RqOtqD7.gif'),
('0206', 'cable reverse curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Coloca una barra recta en una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0206-eOG0r6v.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0206-eOG0r6v.gif'),
('2406', 'cable reverse grip triceps pushdown (sz-bar) (with arm blaster)', 'upper arms', 'cable', 'triceps', 'forearms', '{"forearms"}', 'Sujeta una barra recta a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Activa los tríceps y empuja lentamente la barra hacia abajo hasta que los brazos queden completamente extendidos. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2406-ThKP69G.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2406-ThKP69G.gif'),
('1413', 'cable reverse one arm curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con un agarre supino, con la palma hacia abajo. Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1413-gVlnLIJ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1413-gVlnLIJ.gif'),
('0209', 'cable reverse preacher curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho. Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, con las palmas hacia abajo y los codos completamente extendidos. Agarra las agarraderas del cable con un agarre supino, separadas a la altura de los hombros. Manteniendo la parte superior de los brazos inmóvil, exhala y curva las agarraderas hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0209-IwX5NqK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0209-IwX5NqK.gif'),
('0210', 'cable reverse wrist curl', 'lower arms', 'cable', 'forearms', 'forearms', '{"forearms","wrists"}', 'Sujeta un cable a una polea baja y siéntate en un banco frente a la máquina de cable. Sujeta la agarradera del cable con un agarre prono, con las palmas hacia abajo. Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Haz una pausa por un momento en la parte alta, luego inhala y baja lentamente las muñecas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0210-eYmsEPR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0210-eYmsEPR.gif'),
('0207', 'cable reverse-grip pushdown', 'upper arms', 'cable', 'triceps', 'forearms', '{"forearms"}', 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Usando los tríceps, empuja la barra hacia abajo hasta que los brazos queden completamente extendidos y los tríceps contraídos. Haz una pausa por un momento y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0207-VjYliFZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0207-VjYliFZ.gif'),
('0208', 'cable reverse-grip straight back seated high row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Siéntate frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Jala el cable hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda. Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0208-PNtsX17.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0208-PNtsX17.gif'),
('1320', 'cable rope crossover seated row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado. Jala las cuerdas del cable hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1320-UFGF6gk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1320-UFGF6gk.gif'),
('1321', 'cable rope elevated seated row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Siéntate en el asiento elevado frente a la máquina de cable. Agarra las agarraderas de cuerda con un agarre prono, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia atrás, conservando una ligera flexión en las rodillas. Jala el cable hacia el cuerpo retrayendo los omóplatos y apretando los músculos de la espalda. Haz una pausa por un momento en la posición de contracción completa. Libera lentamente la tensión y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1321-c8oybX6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1321-c8oybX6.gif'),
('1322', 'cable rope extension incline bench row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Coloca un banco inclinado a un ángulo de 45 grados y sujeta una máquina de cable a la polea baja. Sujeta una agarradera de cuerda a la máquina de cable y siéntate en el banco inclinado frente a la máquina. Agarra la agarradera de cuerda con un agarre prono e inclínate hacia adelante, manteniendo la espalda recta. Extiende los brazos por completo, jalando la cuerda hacia la parte superior del pecho mientras mantienes los codos cerca del cuerpo. Aprieta los omóplatos al final del movimiento. Libera lentamente la tensión y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1322-MgKwAAo.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1322-MgKwAAo.gif'),
('1639', 'cable rope hammer preacher curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Sujeta un accesorio de cuerda a una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra). Coloca la parte superior de los brazos contra la almohadilla del banco scott, manteniendo los codos ligeramente flexionados. Manteniendo la parte superior de los brazos inmóvil, exhala y curva la cuerda hacia los hombros contrayendo los bíceps. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la cuerda de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1639-PcPe0P5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1639-PcPe0P5.gif'),
('1724', 'cable rope high pulley overhead tricep extension', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Sujeta una cuerda a una polea alta y ajusta el peso según corresponda. Ponte de pie de espaldas a la máquina de poleas con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos, con las palmas hacia abajo, y lleva las manos por encima de la cabeza. Mantén la parte superior de los brazos cerca de la cabeza y perpendicular al suelo. Baja lentamente la cuerda detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1724-NN8nSNT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1724-NN8nSNT.gif'),
('1725', 'cable rope incline tricep extension', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Sujeta una cuerda a una polea alta y ajusta el banco inclinado a un ángulo cómodo. Ponte de pie de espaldas a la polea con los pies separados a la altura de los hombros. Sujeta la cuerda con un agarre prono y extiende los brazos rectos por encima de la cabeza. Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio. Baja la cuerda detrás de la cabeza flexionando los codos hasta que los antebrazos toquen los bíceps. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1725-ZujAdR9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1725-ZujAdR9.gif'),
('1726', 'cable rope lying on floor tricep extension', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Sujeta una cuerda a una máquina de cable y colócala en la posición más baja. Túmbate en el suelo boca arriba, con la cabeza orientada hacia la máquina de cable. Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos hacia el techo. Mantén la parte superior de los brazos inmóvil y baja lentamente la cuerda hacia la frente, flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1726-U3ffHlY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1726-U3ffHlY.gif'),
('1640', 'cable rope one arm hammer preacher curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Sujeta una agarradera de cuerda a una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la agarradera de cuerda con un agarre supino, con las palmas hacia arriba. Coloca la parte superior del brazo contra la almohadilla del banco scott, manteniendo el codo ligeramente flexionado. Mantén la espalda recta y el core activado durante todo el ejercicio. Curva lentamente la agarradera de cuerda hacia el hombro, manteniendo la parte superior del brazo inmóvil. Aprieta el bíceps en la parte más alta del movimiento y luego baja lentamente la agarradera de cuerda de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1640-4hATdoB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1640-4hATdoB.gif'),
('1323', 'cable rope seated row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Siéntate en la máquina de remo con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las cuerdas del cable con un agarre prono, con las palmas una frente a la otra. Mantén la espalda recta e inclínate ligeramente hacia adelante, manteniendo una ligera flexión en los codos. Jala las cuerdas del cable hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1323-SJqRxOt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1323-SJqRxOt.gif'),
('0211', 'cable russian twists (on stability ball)', 'waist', 'cable', 'abs', 'obliques', '{"obliques","lower back"}', 'Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti. Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado. Gira el torso hacia la derecha, llevando la agarradera del cable hacia la cadera derecha. Haz una pausa por un momento y luego gira el torso hacia la izquierda, llevando la agarradera del cable hacia la cadera izquierda. Continúa alternando los giros el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0211-d9Xaxq6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0211-d9Xaxq6.gif'),
('2144', 'cable seated chest press', 'chest', 'cable', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Ajusta la altura del asiento y las agarraderas del cable a una posición cómoda. Siéntate en el banco con la espalda recta y los pies apoyados planos en el suelo. Sujeta las agarraderas del cable con un agarre prono a la altura del hombro. Empuja las agarraderas hacia adelante y alejándolas del cuerpo, extendiendo los brazos por completo. Haz una pausa por un momento y luego regresa lentamente las agarraderas a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2144-nIR4Rwl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2144-nIR4Rwl.gif'),
('0212', 'cable seated crunch', 'waist', 'cable', 'abs', 'obliques', '{"obliques"}', 'Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas flexionadas. Sujeta la agarradera del cable con ambas manos y colócala detrás de la cabeza. Activa el abdomen y curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa por un momento en la parte alta y luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0212-8xUv4J7.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0212-8xUv4J7.gif'),
('1641', 'cable seated curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en una máquina de cable con los pies apoyados planos en el suelo y la espalda recta. Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo la parte superior de los brazos inmóvil, exhala y curva el accesorio del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1641-8oYqOt9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1641-8oYqOt9.gif'),
('0213', 'cable seated high row (v-bar)', 'back', 'cable', 'lats', 'biceps', '{"biceps","rhomboids","rear deltoids"}', 'Siéntate en la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta el accesorio en V con un agarre prono, con las palmas una frente a la otra y las manos separadas a la altura de los hombros. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Jala el accesorio en V hacia el torso retrayendo los omóplatos y apretando los músculos de la espalda. Haz una pausa por un momento en el punto más alto de la contracción, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0213-pwt0pnM.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0213-pwt0pnM.gif'),
('0214', 'cable seated one arm alternate row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Siéntate en un banco frente a una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera con una mano y mantén el brazo completamente extendido frente a ti. Jala la agarradera hacia el cuerpo, retrayendo el omóplato y manteniendo el codo cerca del costado. Haz una pausa por un momento en la parte más alta del movimiento, apretando los músculos de la espalda. Suelta lentamente la agarradera de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0214-vpp9Ku2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0214-vpp9Ku2.gif'),
('1642', 'cable seated one arm concentration curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta. Sujeta una agarradera del cable con una mano y coloca el codo en la parte interna del muslo, justo arriba de la rodilla. Mantén la parte superior del brazo inmóvil y curva la agarradera del cable hacia el hombro mientras exhalas. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Baja lentamente la agarradera del cable de vuelta a la posición inicial mientras inhalas. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1642-rZ80Gbp.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1642-rZ80Gbp.gif'),
('1643', 'cable seated overhead curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Mantén la parte superior de los brazos inmóvil y los codos cerca de los costados. Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1643-DpWMFP5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1643-DpWMFP5.gif'),
('0215', 'cable seated rear lateral raise', 'shoulders', 'cable', 'delts', 'traps', '{"traps","rhomboids"}', 'Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta las agarraderas del cable con un agarre prono y extiende los brazos rectos frente a ti. Manteniendo los brazos rectos, levántalos lentamente hacia los lados hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0215-x825CZm.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0215-x825CZm.gif'),
('0861', 'cable seated row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta las agarraderas con un agarre prono, manteniendo la espalda recta y los hombros relajados. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0861-fUBheHs.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0861-fUBheHs.gif'),
('0216', 'cable seated shoulder internal rotation', 'shoulders', 'cable', 'delts', 'rotator cuff', '{"rotator cuff","triceps"}', 'Siéntate en un banco o silla frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta la agarradera del cable con el brazo extendido recto frente a ti, paralelo al suelo. Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás y hacia abajo. Rota lentamente el brazo hacia adentro, llevando la agarradera del cable hacia el centro del cuerpo. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0216-YPoVrBi.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0216-YPoVrBi.gif'),
('2399', 'cable seated twist', 'waist', 'cable', 'abs', 'obliques', '{"obliques"}', 'Siéntate en una máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti. Manteniendo el core activado, rota lentamente el torso hacia un lado, jalando el cable a través del cuerpo. Haz una pausa por un momento al final del rango de movimiento y luego rota lentamente de vuelta a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2399-UEjSrKI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2399-UEjSrKI.gif'),
('0218', 'cable seated wide-grip row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Jala la agarradera hacia la parte baja del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto de la contracción. Suelta lentamente la agarradera de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0218-qcY50ZD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0218-qcY50ZD.gif'),
('0219', 'cable shoulder press', 'shoulders', 'cable', 'delts', 'triceps', '{"triceps","upper back"}', 'Ajusta la máquina de cable de modo que las agarraderas queden a la altura del hombro. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con un agarre prono y llévalas hasta la altura del hombro, con los codos flexionados y apuntando hacia afuera. Empuja las agarraderas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0219-PzQanLE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0219-PzQanLE.gif'),
('0220', 'cable shrug', 'back', 'cable', 'traps', 'shoulders', '{"shoulders"}', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta las agarraderas del cable con un agarre prono y deja que los brazos cuelguen frente a ti. Manteniendo los brazos rectos, encoge los hombros hacia las orejas. Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0220-Eg98Ft9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0220-Eg98Ft9.gif'),
('0222', 'cable side bend', 'waist', 'cable', 'abs', 'obliques', '{"obliques"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con una mano. Mantén la espalda recta y el core activado. Flexiona lentamente la cintura hacia un lado, bajando la agarradera del cable hacia la rodilla. Haz una pausa breve y luego vuelve a la posición inicial. Repite del otro lado. Alterna los lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0222-wPypxFY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0222-wPypxFY.gif'),
('0221', 'cable side bend crunch (bosu ball)', 'waist', 'cable', 'abs', 'obliques', '{"obliques"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando la agarradera del cable con una mano. Coloca la otra mano en la cadera. Activa el core y flexiona lentamente la cintura hacia el lado en que sujetas el cable, manteniendo la espalda recta. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0221-qatbkEd.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0221-qatbkEd.gif'),
('0223', 'cable side crunch', 'waist', 'cable', 'abs', 'obliques', '{"obliques"}', 'Coloca un mango de cable en una polea baja y ponte de pie de lado a la máquina. Agarra el mango con la mano más alejada de la máquina y coloca la otra mano en tu cadera. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Con el abdomen activado, flexiona la cintura hacia el lado, bajando el codo hacia la cadera. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0223-q2ADGqV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0223-q2ADGqV.gif'),
('1717', 'cable squat row (with rope attachment)', 'back', 'cable', 'lats', 'biceps', '{"biceps","rhomboids","rear deltoids"}', 'Sujeta una cuerda a una máquina de cable a la altura de la cintura. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Agarra la cuerda con un agarre prono, con las manos separadas a la altura de los hombros. Activa el core y tira de la cuerda hacia tu cuerpo, apretando los omóplatos entre sí. Mantén los codos cerca del cuerpo y continúa tirando hasta que las manos lleguen a tu pecho. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente la cuerda y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1717-f7fnAIB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1717-f7fnAIB.gif'),
('1644', 'cable squatting curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Coloca un mango de cable en el ajuste más bajo de una máquina de cable. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos. Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies. Mientras te agachas, flexiona el mango del cable hacia los hombros, manteniendo los codos cerca de los costados. Haz una pausa breve en la parte alta del movimiento, apretando los bíceps. Baja lentamente el mango del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1644-3XFdb1Z.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1644-3XFdb1Z.gif'),
('0224', 'cable standing back wrist curl', 'lower arms', 'cable', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre prono, con las palmas hacia abajo. Mantén los brazos rectos y los codos cerca de los costados. Flexiona lentamente las muñecas hacia arriba, llevando el mango del cable hacia tu cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0224-VhX2JdE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0224-VhX2JdE.gif'),
('1375', 'cable standing calf raise', 'lower legs', 'cable', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujétate de los mangos de la máquina de cable o coloca una correa de tobillo de cable en tus tobillos. Levanta los talones del suelo extendiendo los tobillos lo más alto posible. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1375-yl2IYyy.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1375-yl2IYyy.gif'),
('0225', 'cable standing cross-over high reverse fly', 'shoulders', 'cable', 'delts', 'trapezius', '{"trapezius","rhomboids","rear deltoids"}', 'Coloca un mango en D en cada lado de una máquina de cable a la altura de los hombros. Ponte de pie en el medio de la máquina de cable con los pies separados a la altura de los hombros. Agarra los mangos con un agarre prono y extiende los brazos hacia los lados, con las palmas hacia adelante. Mantén una ligera flexión en los codos y conserva la espalda recta durante todo el ejercicio. Activa los músculos de los hombros y aprieta los omóplatos entre sí mientras tiras de los mangos hacia la parte delantera de tu cuerpo. Haz una pausa breve en el punto máximo del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0225-P5p0j8B.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0225-P5p0j8B.gif'),
('0226', 'cable standing crunch', 'waist', 'cable', 'abs', 'obliques', '{"obliques"}', 'Coloca un mango de cable en una polea alta y ponte de pie de espaldas a la máquina. Sujeta el mango con ambas manos y colócalo detrás de la cabeza, manteniendo los codos flexionados. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Con el abdomen activado, exhala y flexiona el torso hacia las rodillas, llevando los codos hacia los muslos. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0226-jpgqxiS.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0226-jpgqxiS.gif'),
('0874', 'cable standing crunch (with rope attachment)', 'waist', 'cable', 'abs', 'obliques', '{"obliques"}', 'Sujeta una cuerda a una máquina de cable a la altura del pecho. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos y llévala detrás de la cabeza, manteniendo los codos flexionados. Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando los codos hacia las rodillas. Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0874-XU3ePuv.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0874-XU3ePuv.gif'),
('0227', 'cable standing fly', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Coloca los mangos en los cables a la altura del pecho. Ponte de pie con los pies separados a la altura de los hombros, de espaldas a la máquina de cable. Agarra los mangos con un agarre prono, con las palmas hacia adelante. Da un paso adelante para crear tensión en los cables. Mantén el core activado y la espalda recta durante todo el ejercicio. Con una ligera flexión en los codos, lleva lentamente los brazos hacia adelante y júntalos frente al pecho. Aprieta los músculos del pecho en el punto máximo del movimiento. Invierte lentamente el movimiento, regresando los brazos a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0227-Pr9Rhf4.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0227-Pr9Rhf4.gif'),
('0228', 'cable standing hip extension', 'upper legs', 'cable', 'glutes', 'hamstrings', '{"hamstrings","quadriceps"}', 'Sujeta un cable a una polea baja y ponte de pie de espaldas a la máquina. Coloca el cable alrededor de tu tobillo y ponte de pie con los pies separados a la altura de los hombros. Mantén el core activado y la espalda recta durante todo el ejercicio. Extiende lentamente la pierna hacia atrás, apretando los glúteos en la parte alta del movimiento. Haz una pausa breve y luego vuelve a la posición inicial. Repite el número de repeticiones deseado. Cambia de lado y repite con la otra pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0228-Kpajagk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0228-Kpajagk.gif'),
('0229', 'cable standing inner curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Agarra el mango del cable con un agarre supino, con las palmas hacia arriba. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y flexiona el mango del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el mango del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0229-YwnI4ja.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0229-YwnI4ja.gif'),
('0230', 'cable standing lift', 'waist', 'cable', 'abs', 'obliques', '{"obliques","lower back"}', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con ambas manos y colócalo a la altura de la cintura. Activa el core y mantén la espalda recta durante todo el ejercicio. Manteniendo los brazos rectos, exhala y eleva el mango del cable hacia el hombro opuesto, rotando el torso. Haz una pausa breve en la parte alta, luego inhala y baja lentamente el mango del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0230-qFpAkpP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0230-qFpAkpP.gif'),
('0231', 'cable standing one arm triceps extension', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta el mango del cable con la mano derecha, con la palma hacia abajo, y coloca el brazo completamente extendido y paralelo al suelo. Mantén el codo quieto y cerca del cuerpo. Flexiona lentamente el codo, bajando el mango del cable hacia la parte de atrás de la cabeza. Haz una pausa breve en la parte baja del movimiento, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0231-sYCcnon.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0231-sYCcnon.gif'),
('1376', 'cable standing one leg calf raise', 'lower legs', 'cable', 'calves', 'ankles', '{"ankles","feet"}', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujétate de la máquina de cable para apoyarte. Levanta una pierna del suelo y equilíbrate sobre la otra pierna. Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1376-fgc9Xdl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1376-fgc9Xdl.gif'),
('0232', 'cable standing pulldown (with rope)', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Sujeta una cuerda a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Agarra la cuerda con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira de la cuerda hacia abajo, hacia los muslos, apretando los bíceps. Haz una pausa breve en la parte baja, luego suelta lentamente la cuerda hacia arriba. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0232-CvPn9WV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0232-CvPn9WV.gif'),
('0233', 'cable standing rear delt row (with rope)', 'shoulders', 'cable', 'delts', 'trapezius', '{"trapezius","rhomboids","biceps"}', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta el accesorio del cable con ambas manos, con las palmas una frente a la otra, y retrocede un paso para crear tensión en el cable. Mantén la espalda recta y el core activado. Tira del cable hacia tu cuerpo, apretando los omóplatos entre sí. Haz una pausa breve en el punto máximo del movimiento, luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0233-ZfyAGhK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0233-ZfyAGhK.gif'),
('1727', 'cable standing reverse grip one arm overhead tricep extension', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros. Sujeta el mango del cable con un agarre supino y extiende el brazo por encima de la cabeza, manteniendo el codo cerca de la cabeza. Mantén el brazo superior quieto y baja lentamente el mango del cable detrás de la cabeza flexionando el codo. Haz una pausa breve en la parte baja, luego extiende el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1727-i11JWU7.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1727-i11JWU7.gif'),
('0234', 'cable standing row (v-bar)', 'back', 'cable', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta y el core activado. Tira del accesorio en V hacia tu cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0234-4f8RXP8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0234-4f8RXP8.gif'),
('0235', 'cable standing shoulder external rotation', 'shoulders', 'cable', 'delts', 'rotator cuff', '{"rotator cuff","trapezius"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta el mango del cable con el brazo extendido frente a ti, paralelo al suelo. Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás. Rota lentamente el brazo hacia afuera, alejándolo de tu cuerpo, manteniendo el codo en la misma posición. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0235-FWdVhcW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0235-FWdVhcW.gif'),
('0236', 'cable standing twist row (v-bar)', 'back', 'cable', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Coloca un accesorio en V en una máquina de cable a la altura del pecho. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo. Da un paso atrás para crear tensión en el cable. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira del accesorio en V hacia tu torso retrayendo los omóplatos y flexionando los codos. Mientras tiras, gira el torso hacia un lado, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento, sintiendo la contracción en la parte alta de la espalda. Suelta lentamente la tensión y regresa a la posición inicial, deshaciendo el giro del torso. Repite el movimiento el número de repeticiones deseado, alternando la dirección del giro en cada repetición.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0236-JOZhu2h.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0236-JOZhu2h.gif'),
('1269', 'cable standing up straight crossovers', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Ponte de pie en el medio de una máquina de cable con los pies separados a la altura de los hombros. Sujeta los mangos de los cables con las palmas hacia abajo y los brazos extendidos hacia los lados. Manteniendo los brazos rectos, junta las manos frente a tu cuerpo, cruzándolas una sobre la otra. Haz una pausa breve, luego regresa lentamente a la posición inicial, manteniendo los brazos extendidos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1269-UKWTJWR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1269-UKWTJWR.gif'),
('0238', 'cable straight arm pulldown', 'back', 'cable', 'lats', 'shoulders', '{"shoulders","biceps"}', 'Coloca una barra recta en la polea alta de una máquina de cable. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, manteniendo los brazos rectos y las palmas hacia abajo. Activa los dorsales y tira de la barra hacia abajo, hacia los muslos, manteniendo los brazos rectos durante todo el movimiento. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0238-x69MAlq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0238-x69MAlq.gif'),
('0237', 'cable straight arm pulldown (with rope)', 'back', 'cable', 'lats', 'biceps', '{"biceps","forearms"}', 'Sujeta una cuerda a la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Agarra la cuerda con ambas manos, con las palmas hacia abajo. Extiende completamente los brazos frente a ti, manteniendo los codos ligeramente flexionados. Activa los dorsales y tira lentamente de la cuerda hacia abajo, hacia los muslos, manteniendo los brazos rectos. Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0237-DT14T9T.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0237-DT14T9T.gif'),
('0239', 'cable straight back seated row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms","shoulders"}', 'Siéntate en la máquina de remo con cable con los pies planos sobre los apoyapiés y las rodillas ligeramente flexionadas. Agarra los mangos del cable con un agarre prono, con las palmas hacia abajo. Mantén la espalda recta e inclínate ligeramente hacia adelante desde las caderas. Tira de los mangos del cable hacia tu cuerpo, apretando los omóplatos entre sí. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0239-Tq6gbK6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0239-Tq6gbK6.gif'),
('0240', 'cable supine reverse fly', 'shoulders', 'cable', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Coloca un mango en D en una máquina de cable con polea baja y túmbate boca abajo en un banco plano. Agarra el mango en D con cada mano, con las palmas hacia abajo, y extiende los brazos frente a ti. Manteniendo los brazos rectos, levántalos hacia los lados hasta que estén paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0240-PQcUlDi.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0240-PQcUlDi.gif'),
('2464', 'cable thibaudeau kayak row', 'back', 'cable', 'lats', 'biceps', '{"biceps","rhomboids","rear deltoids"}', 'Coloca un mango de cable en una polea baja y siéntate frente a la máquina con los pies planos en el suelo. Agarra el mango con la mano derecha y extiende completamente el brazo, manteniendo una ligera flexión en el codo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el abdomen activado. Tira del mango hacia tu torso retrayendo el omóplato y flexionando el codo, manteniendo el brazo cerca del cuerpo. Aprieta los músculos de la espalda en la parte alta del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con el brazo izquierdo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2464-ZgwWBoC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2464-ZgwWBoC.gif'),
('0241', 'cable triceps pushdown (v-bar)', 'upper arms', 'cable', 'triceps', 'forearms', '{"forearms"}', 'Coloca un accesorio en V en la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte baja del movimiento, apretando los tríceps. Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0241-gAwDzB3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0241-gAwDzB3.gif'),
('2405', 'cable triceps pushdown (v-bar) (with arm blaster)', 'upper arms', 'cable', 'triceps', 'forearms', '{"forearms"}', 'Coloca un accesorio en V en la máquina de cable en el ajuste más alto. Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos. Haz una pausa breve en la parte baja del movimiento, apretando los tríceps. Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2405-OxJk1fg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2405-OxJk1fg.gif'),
('0242', 'cable tuck reverse crunch', 'waist', 'cable', 'abs', 'hip flexors', '{"hip flexors"}', 'Sujeta un cable a una polea baja y túmbate boca arriba sobre una esterilla. Sujeta el cable con ambas manos y extiende los brazos rectos por encima del pecho. Flexiona las rodillas y levanta las piernas, llevando las rodillas hacia el pecho. Al mismo tiempo, eleva la pelvis hacia el pecho, levantando las caderas del suelo. Haz una pausa breve en la parte alta, luego baja lentamente las piernas y las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0242-TXtXc84.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0242-TXtXc84.gif'),
('0243', 'cable twist', 'waist', 'cable', 'abs', 'obliques', '{"obliques"}', 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados. Activa el core y gira el torso hacia la derecha, tirando del cable a través de tu cuerpo. Haz una pausa breve al final del movimiento, sintiendo la contracción en el abdomen y los oblicuos. Regresa lentamente a la posición inicial, resistiendo la tracción del cable. Repite el movimiento hacia el lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0243-aVs3BR3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0243-aVs3BR3.gif'),
('0862', 'cable twist (up-down)', 'waist', 'cable', 'abs', 'obliques', '{"obliques","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable. Sujeta el mango del cable con ambas manos frente al pecho, manteniendo los brazos ligeramente flexionados. Activa el core y gira lentamente el torso hacia un lado, manteniendo las caderas y las piernas estables. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el giro hacia el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0862-fhZQPlV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0862-fhZQPlV.gif'),
('0244', 'cable twisting pull', 'back', 'cable', 'lats', 'shoulders', '{"shoulders","biceps"}', 'Coloca un mango de cable en una polea baja y ponte de pie frente a la máquina. Agarra el mango con la mano izquierda y aléjate de la máquina, extendiendo completamente el brazo. Coloca los pies separados a la altura de los hombros, con las rodillas ligeramente flexionadas. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira del mango hacia tu cuerpo, rotando el torso hacia la derecha al hacerlo. Aprieta los músculos de la espalda al final del movimiento. Regresa lentamente a la posición inicial, manteniendo la tensión en el cable. Repite el número de repeticiones deseado, luego cambia de lado y realiza el ejercicio con la mano derecha.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0244-zCgxPbV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0244-zCgxPbV.gif'),
('1645', 'cable two arm curl on incline bench', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo. Agarra los mangos del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona los mangos hacia los hombros mientras contraes los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1645-H9y3Dkr.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1645-H9y3Dkr.gif'),
('1728', 'cable two arm tricep kickback', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta el mango del cable en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados. Manteniendo los brazos superiores quietos, extiende los antebrazos hacia atrás hasta que los brazos estén completamente extendidos. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1728-vvNjDJS.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1728-vvNjDJS.gif'),
('0245', 'cable underhand pulldown', 'back', 'cable', 'lats', 'biceps', '{"biceps","forearms"}', 'Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza. Siéntate y agarra la barra de jalón con un agarre supino, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta e inclínate ligeramente hacia atrás. Jala la barra hacia el pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0245-xBYcQHj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0245-xBYcQHj.gif'),
('1270', 'cable upper chest crossovers', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Coloca los mangos en los cables a la altura del pecho. Ponte de pie en el centro de la máquina de cable con un pie ligeramente delante del otro. Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados. Mantén una ligera flexión en los codos y activa el core. Tira de los cables juntos frente al pecho, cruzándolos uno sobre el otro. Aprieta los músculos del pecho en el punto máximo del movimiento. Suelta lentamente los cables de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1270-j7XMAyn.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1270-j7XMAyn.gif'),
('1324', 'cable upper row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Sujeta una barra recta a una máquina de cable a la altura del pecho. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado. Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1324-PQStVXH.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1324-PQStVXH.gif'),
('0246', 'cable upright row', 'shoulders', 'cable', 'delts', 'traps', '{"traps","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta el accesorio del cable con un agarre prono. Mantén la espalda recta y el core activado durante todo el ejercicio. Tira del accesorio del cable directamente hacia arriba, hacia tu barbilla, guiando con los codos. Haz una pausa breve en la parte alta, apretando los omóplatos entre sí. Baja lentamente el accesorio del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0246-cALKspW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0246-cALKspW.gif'),
('1325', 'cable wide grip rear pulldown behind neck', 'back', 'cable', 'lats', 'biceps', '{"biceps","rhomboids","rear deltoids"}', 'Ajusta la máquina de cable de modo que la barra de jalón quede a una altura por encima de tu cabeza. Siéntate y agarra la barra de jalón con un agarre prono amplio. Mantén la espalda recta y el pecho elevado mientras te reclinas ligeramente hacia atrás. Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1325-CmEr4pM.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1325-CmEr4pM.gif'),
('0247', 'cable wrist curl', 'lower arms', 'cable', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Coloca una barra recta en una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros. Apoya los antebrazos en un banco o almohadilla, con las muñecas colgando del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Haz una pausa breve en la parte alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0247-LrV4s90.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0247-LrV4s90.gif'),
('1407', 'calf push stretch with hands against wall', 'lower legs', 'body weight', 'calves', 'hamstrings', '{"hamstrings"}', 'Ponte de pie frente a una pared con los pies separados a la altura de las caderas. Coloca las manos contra la pared a la altura de los hombros. Da un paso atrás con un pie, manteniendo el talón en el suelo y la pierna recta. Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, sintiendo un estiramiento en la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1407-PzNxakt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1407-PzNxakt.gif'),
('1377', 'calf stretch with hands against wall', 'lower legs', 'body weight', 'calves', 'hamstrings', '{"hamstrings"}', 'Ponte de pie frente a una pared con los pies separados a la altura de las caderas. Coloca las manos contra la pared a la altura de los hombros. Da un paso atrás con el pie derecho, manteniendo el talón en el suelo y la pierna recta. Flexiona la rodilla izquierda e inclínate hacia adelante, manteniendo la pierna de atrás recta y el talón en el suelo. Mantén el estiramiento durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1377-m0tCHqc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1377-m0tCHqc.gif'),
('1378', 'calf stretch with rope', 'lower legs', 'rope', 'calves', 'hamstrings', '{"hamstrings"}', 'Ponte de pie frente a una pared u objeto firme con los pies separados a la altura de las caderas. Sujeta los extremos de la cuerda con cada mano y coloca el centro de la cuerda alrededor de la planta del pie derecho. Da un paso atrás con el pie izquierdo, manteniendo el talón en el suelo y la pierna recta. Inclínate hacia adelante, manteniendo la espalda recta, y tira suavemente de la cuerda para estirar la pantorrilla. Mantén el estiramiento durante 20-30 segundos, luego suelta. Repite con la otra pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1378-1LVFcEn.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1378-1LVFcEn.gif'),
('0248', 'cambered bar lying row', 'back', 'barbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Coloca una barra en el suelo y túmbate boca abajo en un banco con el pecho justo en el borde. Estírate hacia abajo y agarra la barra con un agarre prono, un poco más ancho que el ancho de los hombros. Con las piernas rectas y los pies en el suelo, levanta la barra del suelo extendiendo los brazos. Tira de la barra hacia el pecho, juntando los omóplatos. Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0248-R5swFnc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0248-R5swFnc.gif'),
('2963', 'captains chair straight leg raise', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Siéntate en la silla romana con la espalda apoyada en el respaldo y los antebrazos apoyados en las almohadillas. Mantén la parte superior del cuerpo estable y la espalda recta. Activa el abdomen y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2963-weoDEpH.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2963-weoDEpH.gif'),
('1548', 'chair leg extended stretch', 'upper legs', 'body weight', 'quads', 'hamstrings', '{"hamstrings","calves"}', 'Siéntate al borde de una silla con la espalda recta y los pies planos en el suelo. Extiende una pierna recta frente a ti, manteniendo el talón en el suelo. Inclínate ligeramente hacia adelante, sintiendo un estiramiento en los cuádriceps. Mantén esta posición durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1548-xGgAGPm.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1548-xGgAGPm.gif'),
('1271', 'chest and front of shoulder stretch', 'chest', 'body weight', 'pectorals', 'deltoids', '{"deltoids"}', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos rectos frente a ti a la altura de los hombros. Cruza los brazos frente a tu cuerpo, con el brazo derecho sobre el brazo izquierdo. Entrelaza los dedos y presiona las palmas entre sí. Aprieta suavemente los omóplatos entre sí y empuja las manos hacia adelante, sintiendo un estiramiento en el pecho y la parte delantera de los hombros. Mantén el estiramiento durante 20-30 segundos, luego suelta. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1271-Uto7l43.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1271-Uto7l43.gif'),
('0251', 'chest dip', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Colócate en las barras paralelas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0251-9WTm7dq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0251-9WTm7dq.gif'),
('1430', 'chest dip (on dip-pull-up cage)', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ajusta las barras de fondos a una altura que te permita agarrarlas cómodamente. Ponte de pie entre las barras y coloca las manos en cada barra, un poco más separadas que el ancho de los hombros. Salta y estira los brazos, sosteniendo el peso de tu cuerpo sobre las barras. Flexiona las rodillas y cruza los tobillos detrás de ti. Baja el cuerpo flexionando los codos, manteniendo el pecho elevado y los hombros bajos. Continúa bajando hasta que los hombros queden por debajo de los codos o hasta que sientas un estiramiento en el pecho. Empuja con las palmas y extiende los codos para subir el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1430-XgWyAiA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1430-XgWyAiA.gif'),
('2462', 'chest dip on straight bar', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Agarra las barras paralelas con las palmas hacia abajo y los brazos completamente extendidos. Flexiona las rodillas y cruza los tobillos. Baja el cuerpo flexionando los brazos hasta que los hombros queden por debajo de los codos. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2462-LQFOrMn.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2462-LQFOrMn.gif'),
('1272', 'chest stretch with exercise ball', 'chest', 'stability ball', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y la espalda recta. Sujeta el balón de ejercicio con ambas manos y extiende los brazos rectos frente a ti. Lleva lentamente el balón de ejercicio hacia tu pecho, sintiendo un estiramiento en los músculos del pecho. Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1272-ykA5tU7.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1272-ykA5tU7.gif'),
('3216', 'chest tap push-up (male)', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Mientras te bajas, toca tu pecho con la mano derecha. Empújate de vuelta hacia arriba hasta la posición inicial. Repite el movimiento, esta vez tocando tu pecho con la mano izquierda. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3216-7E06s6d.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3216-7E06s6d.gif'),
('1326', 'chin-up', 'back', 'body weight', 'lats', 'biceps', '{"biceps","forearms"}', 'Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1326-T2mxWqc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1326-T2mxWqc.gif'),
('0253', 'chin-ups (narrow parallel grip)', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","forearms"}', 'Cuélgate de una barra de dominadas con un agarre paralelo estrecho, con las palmas hacia ti. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0253-G70mEAJ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0253-G70mEAJ.gif'),
('0257', 'circles knee stretch', 'lower legs', 'body weight', 'calves', 'hamstrings', '{"hamstrings","quadriceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas. Flexiona ligeramente las rodillas y levanta los talones del suelo, equilibrándote sobre las puntas de los pies. Manteniendo las rodillas flexionadas, gira las rodillas en un movimiento circular, primero en el sentido de las agujas del reloj y luego en sentido contrario. Realiza el movimiento el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0257-X7jbxra.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0257-X7jbxra.gif'),
('1273', 'clap push up', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado. Empuja con las palmas de forma explosiva para impulsar tu cuerpo fuera del suelo. Mientras estás en el aire, junta las manos en un aplauso antes de aterrizar de vuelta en la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1273-wigSg76.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1273-wigSg76.gif'),
('0258', 'clock push-up', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders","core"}', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Mientras bajas, gira el cuerpo hacia la izquierda, extendiendo el brazo izquierdo recto hacia el lado. Empuja de vuelta hacia arriba hasta la posición inicial, mientras giras el cuerpo hacia el centro. Repite la flexión de brazos, esta vez girando el cuerpo hacia la derecha y extendiendo el brazo derecho hacia el lado. Continúa alternando lados en cada repetición.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0258-CMAxnsG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0258-CMAxnsG.gif'),
('1327', 'close grip chin-up', 'back', 'body weight', 'lats', 'biceps', '{"biceps","forearms"}', 'Agarra la barra de dominadas con las palmas hacia ti y las manos separadas a la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1327-VnfUNW7.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1327-VnfUNW7.gif'),
('0259', 'close-grip push-up', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Comienza en posición de plancha alta con las manos juntas, directamente debajo de los hombros. Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0259-x6KpKpq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0259-x6KpKpq.gif'),
('2398', 'close-grip push-up (on knees)', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Comienza apoyándote sobre las manos y las rodillas, con las manos separadas a la altura de los hombros y las rodillas separadas a la altura de las caderas. Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Haz una pausa breve cuando tu pecho esté justo por encima del suelo. Empuja con las palmas para estirar los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2398-v3vLFW0.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2398-v3vLFW0.gif'),
('0260', 'cocoons', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors","lower back"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0260-SLKj2pX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0260-SLKj2pX.gif'),
('1468', 'crab twist toe touch', 'waist', 'body weight', 'abs', 'obliques', '{"obliques","hip flexors"}', 'Comienza sentado en el suelo con las rodillas flexionadas y los pies planos en el suelo. Coloca las manos detrás de ti, con los dedos apuntando hacia los pies, y levanta las caderas del suelo. Extiende una pierna recta frente a ti mientras al mismo tiempo llevas la mano contraria hacia los dedos del pie. Regresa a la posición inicial y repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1468-xgsGFVM.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1468-xgsGFVM.gif'),
('0262', 'cross body crunch', 'waist', 'body weight', 'abs', 'obliques', '{"obliques"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta la parte superior del cuerpo del suelo y gira para llevar el codo derecho hacia la rodilla izquierda. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite en el otro lado, llevando el codo izquierdo hacia la rodilla derecha. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0262-rbu5UUb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0262-rbu5UUb.gif'),
('0267', 'crunch (hands overhead)', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende los brazos rectos por encima de la cabeza. Activando el abdomen, levanta la parte superior del cuerpo del suelo, flexionándote hacia adelante en dirección a las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0267-kjJ3VoQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0267-kjJ3VoQ.gif'),
('0271', 'crunch (on stability ball)', 'waist', 'stability ball', 'abs', 'hip flexors', '{"hip flexors"}', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo hacia las rodillas, flexionando el torso hacia adelante. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0271-MCUhf1F.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0271-MCUhf1F.gif'),
('0272', 'crunch (on stability ball, arms straight)', 'waist', 'stability ball', 'abs', 'hip flexors', '{"hip flexors"}', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Reclínate sobre el balón hasta que la zona lumbar esté apoyada y la parte superior del cuerpo quede paralela al suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del balón, flexionando los hombros hacia las caderas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0272-Sn8wxAI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0272-Sn8wxAI.gif');
